 page.evaluate("S.role='coordinacion_academica';__testPanel.innerHTML=jaguarOperations.html()");page.locator('#jop_cycle').fill('2026-2027');page.locator('#jop_student').fill('100');page.get_by_role('button',name='Evaluar acreditación proyectada',exact=True).click();page.get_by_text('Proyección calculada',exact=True).wait_for();assert 'await_regularization' in page.locator('#jop_projection').inner_text();page.get_by_role('button',name='Consultar convocatorias y plan',exact=True).click();page.get_by_text('Proponer convocatoria · Plan V2',exact=True).wait_for();page.locator('#jop_kind').select_option('recourse');assert page.locator('#jop_cap').input_value()=='7' and page.locator('#jop_cap').is_disabled();page.locator('#jop_start').fill('2027-07-01');page.locator('#jop_end').fill('2027-07-03');page.locator('#jop_modality').fill('Intensivo');page.locator('#jop_b2').check();page.locator('#jop_reason').fill('Motivo de regularización ficticio');page.get_by_role('button',name='Registrar propuesta',exact=True).click();page.wait_for_function('__requests.length===3');assert page.evaluate('__requests[2].rules.blocks[0].period')==2
